"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[3276],{5182:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"self<C,S>","desc":"Type used to describe the `self` object in Client functions.\\nEach client function has its own [Mutex], with a global lock and one lock per player.\\n```lua\\nfunction MyService.Client.PrintPlayer(self: fish.self<client, server>)\\n\\tprint(self.Player)\\n\\t\\n\\t--\x3e Mutex with locking & unlocking\\n\\tself.Mutex:Lock()\\n\\t-- Run critical section\\n\\tself.Mutex:Unlock()\\n\\n\\t--\x3e Locking is re-entrant; this only releases once the matching Unlock has run\\n\\tself.Mutex:Lock()\\n\\tself.Mutex:Unlock()\\n\\tself.Mutex:Unlock()\\n\\n\\t--\x3e Locking this player only, warning if the lock is held for longer than 5 seconds\\n\\tself.Mutex:Lock(5, self.Player)\\n\\t-- Run critical section\\n\\tself.Mutex:Unlock(self.Player)\\n\\t\\n\\t--\x3e Mutex with wrapping; the wrapped function runs on its own thread and is given its own silent assert\\n\\tlocal success, result = self.Mutex:Wrap(nil, function(confirm, parameter)\\n\\t\\t-- Run critical section\\n\\t\\treturn parameter\\n\\tend, 1)\\n\\tprint(success, result) --\x3e Output: true, 1\\n\\n\\t--\x3e Silent assert (stops the current thread from continuing, equivalent to a return statement)\\n\\tself.confirm(success)\\n\\tprint(\\"This print statement won\'t run if success == false!\\")\\nend\\n```","lua_type":"C & { Player: Player, Server: S, Mutex: Mutex, confirm: Confirm }","source":{"line":51,"path":"src/init.lua"}},{"name":"ServiceToReference<T>","desc":"A type used to wrap an entire service\'s client table with ToClient<type>","lua_type":"{[any]: ToClient<type>}","source":{"line":63,"path":"src/init.lua"}},{"name":"ServiceDef<T>","desc":"The definition of a service when created using `fish.service(name, serviceDef)`","lua_type":"T & { Client: {[any]: any}?, Start: ((any) -> any)? }","source":{"line":13,"path":"src/Types.lua"}},{"name":"Service<T>","desc":"A service as seen in the server context","lua_type":"T & { Client: { Server: T, Signal: { Server: T } }, Start: (any) -> any, LoadPriority: number? }","source":{"line":23,"path":"src/Types.lua"}},{"name":"ServiceRef","desc":"A reference to a service from the client context","lua_type":"{ [any]: any }","source":{"line":39,"path":"src/Types.lua"}},{"name":"ControllerDef<T>","desc":"The definition of a controller when created using `fish.controller(name, controllerDef)`","lua_type":"T & { Start: ((any) -> any)? }","source":{"line":48,"path":"src/Types.lua"}},{"name":"Controller<T>","desc":"A controller as seen in the client context","lua_type":"T & { Start: (any) -> any, LoadPriority: number? }","source":{"line":57,"path":"src/Types.lua"}},{"name":"Confirm","desc":"A silent assert. When the given value is falsy the current thread is stopped, which is\\nequivalent to returning early; otherwise the value is returned with `nil` removed from\\nits type.","lua_type":"<T>(value: T?) -> T","source":{"line":69,"path":"src/Types.lua"}},{"name":"Mutex","desc":"Thread locking for a client function.","lua_type":"{ Lock: (self, number?, Player?) -> (), Unlock: (self, Player?) -> (), Wrap: <A..., R...>(self, number?, (Confirm, A...) -> R..., A...) -> (boolean, R...), WrapPlayer: <A..., R...>(self, number?, Player, (Confirm, A...) -> R..., A...) -> (boolean, R...) }","source":{"line":76,"path":"src/Types.lua"}},{"name":"ServiceMetadata","desc":"Bookkeeping attached to a service while it is registered; removed once the service starts","lua_type":"{ Instance: ModuleScript, Name: string }","ignore":true,"source":{"line":89,"path":"src/Types.lua"}},{"name":"ControllerMetadata","desc":"Bookkeeping attached to a controller while it is registered; removed once the controller starts","lua_type":"{ Instance: ModuleScript }","ignore":true,"source":{"line":100,"path":"src/Types.lua"}},{"name":"RegisteredService","desc":"A registered service as the framework handles it internally, before it is handed back to the caller as [Service]","lua_type":"{ Client: {[any]: any}?, Start: (any) -> any, LoadPriority: number?, __fishMetadata: ServiceMetadata?, [any]: any }","ignore":true,"source":{"line":110,"path":"src/Types.lua"}},{"name":"RegisteredController","desc":"A registered controller as the framework handles it internally, before it is handed back to the caller as [Controller]","lua_type":"{ Client: {[any]: any}?, Start: (any) -> any, LoadPriority: number?, __fishMetadata: ControllerMetadata?, [any]: any }","ignore":true,"source":{"line":124,"path":"src/Types.lua"}},{"name":"ToClient","desc":"A type function used to convert various server implementations into their client counterpart\\n\\t","lua_type":"(type: type) -> (ClientRemoteSignal | ClientRemoteProperty | ((...any) -> Promise.TypedPromise<...any>) | never)","source":{"line":609,"path":"src/Types.lua"}}],"name":"Types","desc":"Global types used throughout the framework","source":{"line":5,"path":"src/Types.lua"}}')}}]);